"use client";
import {ArrowLeft,BriefcaseBusiness,Building2,Check,ChevronDown,ChevronRight,ClipboardCheck,House,MapPin,Minus,Package,Plus,Trash2,Users,UsersRound} from "lucide-react";
import {motion} from "motion/react";
import Link from "next/link";
import {useRouter} from "next/navigation";
import {FormEvent,useCallback,useEffect,useRef,useState} from "react";
import {BottomSheet} from "@/components/dpr/bottom-sheet";
import {DPRDeleteMenu} from "@/components/dpr/dpr-delete-menu";
import {DPRReview} from "@/components/dpr/dpr-review";
import {ManpowerScreen} from "@/components/dpr/manpower-screen";
import {MaterialsScreen} from "@/components/dpr/materials-screen";
import {SitePhotosScreen} from "@/components/dpr/site-photos-screen";
import {SiteVisitForm,SiteVisitScreen} from "@/components/dpr/site-visit-screen";
import {MobileOptionPicker} from "@/components/dpr/mobile-option-picker";
import {StoredPhoto} from "@/components/dpr/stored-photo";
import {TomorrowPlanScreen} from "@/components/dpr/tomorrow-plan-screen";
import {SectionCard} from "@/components/dpr/section-card";
import {WorkDoneScreen} from "@/components/dpr/work-done-screen";
import {completedRequired,completionPercent,formatDPRDate,loadDPRRecords,missingSections,recordKey,replaceDPRRecords,saveDPR,todayISO} from "@/lib/dpr";
import {migrateEmbeddedPhotoRecords} from "@/lib/photo-store";
import {resolveProject} from "@/lib/projects";
import type {DPR,DPRManpower,DPRMaterial,DPRWork,SiteVisit} from "@/types";

type Sheet="work"|"manpower"|"material"|"visit"|"confirm"|null;
const activities:Record<string,string>={"Cable Tray Installation":"m","Conduit Laying":"m","Cable Pulling":"m","Panel Installation":"nos","Earthing":"m","Light Fixture Installation":"nos","Testing & Commissioning":"job","Other":""};
const materialUnits:Record<string,string>={"Electrical Cable":"m","Cable Tray":"m","PVC Conduit":"m","GI Conduit":"m","Earthing Cable":"m","Light Fixture":"nos","Distribution Board":"nos","Cable Gland":"nos","Other":""};
const roles=["Electrician","Helper","Supervisor","Technician","Welder","Plumber","Other"];
const workUnits=["m","m²","m³","nos","kg","lot","job"];
const id=()=>crypto.randomUUID();

export function DPREditor({projectId,date}:{projectId:string;date:string}){const router=useRouter();const project=resolveProject(projectId);const[dpr,setDpr]=useState<DPR>({id:"",projectId,date,status:"draft",work:[],manpower:[],materials:[],photos:[],siteVisits:[],tomorrowPlan:[],generalRemarks:"",updatedAt:""});const[ready,setReady]=useState(false);const[exists,setExists]=useState(false);const[saveState,setSaveState]=useState<"saving"|"saved">("saved");const[sheet,setSheet]=useState<Sheet>(null);const[editing,setEditing]=useState<string|null>(null);const[review,setReview]=useState(false);const[success,setSuccess]=useState(false);const[focusedWork,setFocusedWork]=useState(false);const[focusedManpower,setFocusedManpower]=useState(false);const[focusedMaterials,setFocusedMaterials]=useState(false);const[focusedPhotos,setFocusedPhotos]=useState(false);const[focusedVisit,setFocusedVisit]=useState(false);const[focusedTomorrow,setFocusedTomorrow]=useState(false);
 const[saveFailed,setSaveFailed]=useState(false);const latestDprRef=useRef(dpr);const submitLockRef=useRef(false);
 useEffect(()=>{latestDprRef.current=dpr},[dpr]);
 useEffect(()=>{let cancelled=false;const timer=window.setTimeout(async()=>{let records=loadDPRRecords();try{const migration=await migrateEmbeddedPhotoRecords(records);records=migration.records;if(migration.changed)replaceDPRRecords(records)}catch{}const stored=records[recordKey(projectId,date)];if(stored&&!cancelled){setDpr(stored);setExists(true)}if(!cancelled)setReady(true)},0);return()=>{cancelled=true;window.clearTimeout(timer)}},[projectId,date]);
 useEffect(()=>{if(!ready||!exists||dpr.status==="submitted")return;const savingTimer=window.setTimeout(()=>{setSaveFailed(false);setSaveState("saving")},0);const timer=window.setTimeout(()=>{try{saveDPR(dpr);setSaveState("saved")}catch(error){console.error("Could not autosave DPR",error);setSaveFailed(true)}},450);return()=>{window.clearTimeout(savingTimer);window.clearTimeout(timer)}},[dpr,ready,exists]);
 useEffect(()=>{if(!ready||!exists)return;return()=>{const latest=latestDprRef.current;if(latest.status!=="submitted")try{saveDPR(latest)}catch(error){console.error("Could not flush DPR changes",error)}}},[ready,exists]);
 useEffect(()=>{if(!ready)return;const syncHash=()=>{setFocusedWork(location.hash==="#work");setFocusedManpower(location.hash==="#manpower");setFocusedMaterials(location.hash==="#materials");setFocusedPhotos(location.hash==="#photos");setFocusedVisit(location.hash==="#visit");setFocusedTomorrow(location.hash==="#tomorrow")};syncHash();window.addEventListener("hashchange",syncHash);if(location.hash&&!['#work','#manpower','#materials','#photos','#visit','#tomorrow'].includes(location.hash))window.setTimeout(()=>document.querySelector(location.hash)?.scrollIntoView({behavior:"smooth",block:"start"}),150);return()=>window.removeEventListener("hashchange",syncHash)},[ready]);
 const update=useCallback(<K extends keyof DPR>(key:K,value:DPR[K])=>setDpr(current=>({...current,[key]:value})),[]);
 const completed=completedRequired(dpr),percent=completionPercent(dpr),missing=missingSections(dpr);
 const totalManpower=dpr.manpower.reduce((sum,row)=>sum+row.inHouse+row.subcontractor,0);
 const open=(type:Sheet,itemId?:string)=>{setEditing(itemId??null);setSheet(type)};
 const remove=<K extends "work"|"manpower"|"materials"|"siteVisits"|"tomorrowPlan">(key:K,itemId:string)=>setDpr(current=>({...current,[key]:current[key].filter(item=>item.id!==itemId)}));
 const reviewNow=()=>{setReview(true);window.scrollTo({top:0,behavior:"smooth"})};
 const submit=()=>{if(submitLockRef.current)return;if(missing.length){setSheet(null);setReview(true);return}submitLockRef.current=true;const next={...dpr,status:"submitted" as const,updatedAt:new Date().toISOString()};try{saveDPR(next)}catch(error){submitLockRef.current=false;console.error("Could not submit DPR",error);setSaveFailed(true);setSheet(null);return}setDpr(next);setSheet(null);setSuccess(true)};
 const afterDelete=()=>router.replace(date===todayISO()?`/today?project=${projectId}`:`/calendar?project=${projectId}&date=${date}`);
 const continueToManpower=()=>{setFocusedWork(false);setFocusedManpower(true);window.history.replaceState(null,"",`${location.pathname}${location.search}#manpower`);window.scrollTo({top:0,behavior:"smooth"})};
 const continueToMaterials=()=>{setFocusedManpower(false);setFocusedMaterials(true);window.history.replaceState(null,"",`${location.pathname}${location.search}#materials`);window.scrollTo({top:0,behavior:"smooth"})};
 const continueToPhotos=()=>{setFocusedMaterials(false);setFocusedPhotos(true);window.history.replaceState(null,"",`${location.pathname}${location.search}#photos`);window.scrollTo({top:0,behavior:"smooth"})};
 const continueToVisit=()=>{setFocusedPhotos(false);setFocusedVisit(true);window.history.replaceState(null,"",`${location.pathname}${location.search}#visit`);window.scrollTo({top:0,behavior:"smooth"})};
 const continueToTomorrow=()=>{setFocusedVisit(false);setFocusedTomorrow(true);window.history.replaceState(null,"",`${location.pathname}${location.search}#tomorrow`);window.scrollTo({top:0,behavior:"smooth"})};
 const reviewFromTomorrow=()=>{setFocusedTomorrow(false);setReview(true);window.history.replaceState(null,"",`${location.pathname}${location.search}`);window.scrollTo({top:0,behavior:"smooth"})};
 const editFromReview=(section:string)=>{setReview(false);window.setTimeout(()=>{if(section==="remarks"){document.getElementById("remarks")?.scrollIntoView({behavior:"smooth",block:"start"});return}window.history.replaceState(null,"",`${location.pathname}${location.search}#${section}`);window.dispatchEvent(new HashChangeEvent("hashchange"));window.scrollTo({top:0,behavior:"smooth"})},0)};
 if(!ready)return <div className="grid min-h-[70dvh] place-items-center text-[14px] text-[#71717a]">Opening today&apos;s DPR…</div>;
 if(!exists)return <div className="grid min-h-[70dvh] place-items-center px-4"><div className="text-center"><h1 className="text-[20px] font-semibold">No DPR for this date</h1><p className="mt-2 text-[14px] text-[#71717a]">Create it from Today or Calendar first.</p><Link href={`/calendar?project=${projectId}&date=${date}`} className="mt-5 inline-grid h-11 place-items-center rounded-[10px] bg-[#18181b] px-5 text-[14px] font-semibold text-white">Back to calendar</Link></div></div>;
 if(dpr.status==="submitted")return <DPRReview dpr={dpr} readOnly onBack={()=>router.replace(date===todayISO()?`/today?project=${projectId}`:`/calendar?project=${projectId}&date=${date}`)}/>;
 if(success)return <Success projectId={projectId} date={date} onDone={()=>router.push(`/today?project=${projectId}`)}/>;
 if(review)return <><DPRReview dpr={dpr} onBack={()=>setReview(false)} onEdit={editFromReview} onSubmit={()=>setSheet("confirm")}/><EditorSheets sheet={sheet} setSheet={setSheet} editing={editing} dpr={dpr} setDpr={setDpr} remove={remove} submit={submit}/>{saveFailed&&<SaveErrorNotice/>}</>;
 if(focusedWork)return <><WorkDoneScreen dpr={dpr} saveState={saveState} completed={completed} percent={percent} onAdd={()=>open("work")} onEdit={itemId=>open("work",itemId)} onDuplicate={row=>setDpr(current=>({...current,work:[...current.work,{...row,id:id()}]}))} onDelete={itemId=>setDpr(current=>({...current,work:current.work.filter(row=>row.id!==itemId)}))} onNext={continueToManpower} onDprDeleted={afterDelete}/><EditorSheets sheet={sheet} setSheet={setSheet} editing={editing} dpr={dpr} setDpr={setDpr} remove={remove} submit={submit}/>{saveFailed&&<SaveErrorNotice/>}</>;
 if(focusedManpower)return <><ManpowerScreen dpr={dpr} saveState={saveState} completed={completed} percent={percent} onAdd={()=>open("manpower")} onEdit={itemId=>open("manpower",itemId)} onDuplicate={row=>setDpr(current=>({...current,manpower:[...current.manpower,{...row,id:id()}]}))} onDelete={itemId=>setDpr(current=>({...current,manpower:current.manpower.filter(row=>row.id!==itemId)}))} onNext={continueToMaterials} onDprDeleted={afterDelete}/><EditorSheets sheet={sheet} setSheet={setSheet} editing={editing} dpr={dpr} setDpr={setDpr} remove={remove} submit={submit}/>{saveFailed&&<SaveErrorNotice/>}</>;
 if(focusedMaterials)return <><MaterialsScreen dpr={dpr} saveState={saveState} completed={completed} percent={percent} onAdd={()=>open("material")} onEdit={itemId=>open("material",itemId)} onDuplicate={row=>setDpr(current=>({...current,materials:[...current.materials,{...row,id:id()}]}))} onDelete={itemId=>setDpr(current=>({...current,materials:current.materials.filter(row=>row.id!==itemId)}))} onNext={continueToPhotos} onDprDeleted={afterDelete}/><EditorSheets sheet={sheet} setSheet={setSheet} editing={editing} dpr={dpr} setDpr={setDpr} remove={remove} submit={submit}/>{saveFailed&&<SaveErrorNotice/>}</>;
 if(focusedPhotos)return <><SitePhotosScreen dpr={dpr} saveState={saveState} completed={completed} percent={percent} onAdd={photos=>setDpr(current=>({...current,photos:[...current.photos,...photos]}))} onCaption={(photoId,caption)=>setDpr(current=>({...current,photos:current.photos.map(photo=>photo.id===photoId?{...photo,caption}:photo)}))} onDelete={photoId=>setDpr(current=>({...current,photos:current.photos.filter(photo=>photo.id!==photoId)}))} onNext={continueToVisit} onDprDeleted={afterDelete}/>{saveFailed&&<SaveErrorNotice/>}</>;
 if(focusedVisit)return <><SiteVisitScreen dpr={dpr} saveState={saveState} completed={completed} percent={percent} onUpsert={visit=>setDpr(current=>({...current,siteVisits:current.siteVisits.some(item=>item.id===visit.id)?current.siteVisits.map(item=>item.id===visit.id?visit:item):[...current.siteVisits,visit]}))} onDelete={visitId=>setDpr(current=>({...current,siteVisits:current.siteVisits.filter(visit=>visit.id!==visitId)}))} onNext={continueToTomorrow} onDprDeleted={afterDelete}/>{saveFailed&&<SaveErrorNotice/>}</>;
 if(focusedTomorrow)return <><TomorrowPlanScreen dpr={dpr} saveState={saveState} completed={completed} percent={percent} onUpsert={activity=>setDpr(current=>({...current,tomorrowPlan:current.tomorrowPlan.some(item=>item.id===activity.id)?current.tomorrowPlan.map(item=>item.id===activity.id?activity:item):[...current.tomorrowPlan,activity]}))} onDuplicate={activity=>setDpr(current=>({...current,tomorrowPlan:[...current.tomorrowPlan,{...activity,id:id()}]}))} onDelete={activityId=>setDpr(current=>({...current,tomorrowPlan:current.tomorrowPlan.filter(activity=>activity.id!==activityId)}))} onReview={reviewFromTomorrow} onDprDeleted={afterDelete}/>{saveFailed&&<SaveErrorNotice/>}</>;
 return <div className="min-h-dvh pb-[calc(90px+env(safe-area-inset-bottom))] lg:pb-12">{saveFailed&&<SaveErrorNotice/>}<header className="sticky top-0 z-40 border-b border-[#e4e4e7] bg-white/95 backdrop-blur-md"><div className="mx-auto flex h-16 max-w-[1180px] items-center justify-between px-4 sm:px-6"><Link href={`/today?project=${projectId}`} className="focus-ring flex h-11 items-center gap-2 rounded-[10px] text-[15px] font-semibold"><ArrowLeft size={19}/><span>Today&apos;s DPR</span></Link><div className="flex items-center gap-2"><motion.span key={saveState} initial={{opacity:0,y:2}} animate={{opacity:1,y:0}} className="text-[13px] text-[#71717a]">{saveState==="saving"?"Saving…":"Saved ✓"}</motion.span><DPRDeleteMenu dpr={dpr} onDeleted={afterDelete}/></div></div></header>
  <main className="mx-auto grid w-full min-w-0 max-w-[1180px] gap-5 px-4 py-4 sm:px-6 lg:grid-cols-[minmax(0,800px)_300px] lg:items-start lg:gap-6 lg:py-8"><div className="min-w-0 space-y-3 lg:space-y-5"><div className="mb-5 min-w-0"><div className="flex min-w-0 items-center gap-2"><h1 className="min-w-0 truncate text-[24px] font-semibold sm:text-[20px]">{project.name}</h1><span className="shrink-0 rounded-full bg-[#fdeceb] px-2.5 py-1 text-[11px] font-semibold text-[#c43f3b]">Draft</span></div><p className="mt-1 text-[14px] text-[#71717a]">{formatDPRDate(date)} · {project.workType}</p></div>
   <nav className="hidden gap-2 lg:flex" aria-label="DPR sections">{[["work","Work"],["manpower","Manpower"],["materials","Materials"],["photos","Photos"],["visit","Visit"],["tomorrow","Tomorrow"]].map(([anchor,name],index)=>{const done=index===4?dpr.siteVisits.length>0:index===0?dpr.work.length>0:index===1?dpr.manpower.length>0:index===2?dpr.materials.length>0:index===3?dpr.photos.length>0:dpr.tomorrowPlan.length>0;return <a key={anchor} href={`#${anchor}`} className="focus-ring flex h-10 shrink-0 items-center gap-1.5 rounded-full border border-[#e4e4e7] bg-white px-3 text-[12px] font-medium"><span className={`grid size-4 place-items-center rounded-full text-[9px] ${done?"bg-[#eaf5ef] text-[#3f8f6b]":"bg-[#f4f4f5] text-[#a1a1aa]"}`}>{done?<Check size={10}/>:index===4?"○":"·"}</span>{name}</a>})}</nav><div className="rounded-xl border border-[#e4e4e7] bg-white p-4 lg:hidden"><div className="flex items-center justify-between text-[13px]"><span className="font-medium">DPR progress</span><strong>{completed} / 5</strong></div><p className="mt-1 text-[12px] text-[#71717a]">{completed} of 5 required sections complete</p><div className="mt-3 h-1.5 overflow-hidden rounded-full bg-[#f0f0f2]"><motion.div animate={{width:`${percent}%`}} className="h-full rounded-full bg-[#e14d48]"/></div></div>
   <SectionCard id="work" number="01" title="Work Done" supporting="What was done today?" action={<AddButton onClick={()=>open("work")}>Add activity</AddButton>}><Rows empty="No work added yet.">{dpr.work.map(row=><WorkRow key={row.id} row={row} onEdit={()=>open("work",row.id)}/>)}</Rows></SectionCard>
   <SectionCard id="manpower" number="02" title="Manpower" supporting="Who worked on site today?" action={<AddButton onClick={()=>open("manpower")}>Add manpower</AddButton>}><Rows empty="No manpower added yet.">{dpr.manpower.map(row=><ListRow key={row.id} icon={<Users size={17}/>} title={row.role} value={`${row.inHouse+row.subcontractor}`} onClick={()=>open("manpower",row.id)}/>)}</Rows>{dpr.manpower.length>0&&<div className="mt-4 flex justify-between border-t border-[#e4e4e7] pt-4 text-[14px] font-semibold"><span>Total manpower</span><span>{totalManpower}</span></div>}</SectionCard>
   <SectionCard id="materials" number="03" title="Materials Used" supporting="What materials were used today?" action={<AddButton onClick={()=>open("material")}>Add material</AddButton>}><Rows empty="No materials added yet.">{dpr.materials.map(row=><ListRow key={row.id} icon={<Package size={17}/>} title={row.material} subtitle={row.remarks} value={`${row.quantity} ${row.unit}`} onClick={()=>open("material",row.id)}/>)}</Rows></SectionCard>
   <SectionCard id="photos" number="04" title="Site Photos" supporting="Add photos showing today's site progress." action={<AddButton onClick={continueToPhotos}>Manage photos</AddButton>}>{dpr.photos.length===0?<Empty text="No site photos added yet."/>:<div className="grid grid-cols-2 gap-3 sm:grid-cols-3">{dpr.photos.map(photo=><button key={photo.id} onClick={continueToPhotos} className="overflow-hidden rounded-xl border border-[#e4e4e7] text-left"><StoredPhoto src={photo.src} alt={photo.caption||"Site progress"} className="aspect-[4/3] w-full object-cover"/><span className="block truncate p-2 text-[12px] font-medium">{photo.caption||photo.name||"Site progress"}</span></button>)}</div>}</SectionCard>
   <SectionCard id="visit" number="05" title="Site Visit / Feedback" supporting="Record feedback if a senior person or client visited today." optional action={<AddButton onClick={()=>open("visit")}>Add visit</AddButton>}>{dpr.siteVisits.length===0?<Empty text="No site visit recorded today."/>:<div className="space-y-4">{dpr.siteVisits.map(visit=><button key={visit.id} onClick={()=>open("visit",visit.id)} className="w-full border-l-2 border-[#e14d48] pl-4 text-left"><span className="text-[12px] font-semibold text-[#71717a]">{visit.visitTime}</span><p className="mt-1 text-[15px] font-semibold">{visit.visitorName} <span className="font-normal text-[#71717a]">{visit.designation}</span></p><p className="mt-2 text-[13px] leading-5 text-[#71717a]">{visit.feedback}</p>{visit.actionRequired&&<span className="mt-2 inline-flex rounded-full bg-[#fff5e5] px-2 py-1 text-[10px] font-semibold text-[#9b6726]">Action required</span>}</button>)}</div>}</SectionCard>
   <SectionCard id="tomorrow" number="06" title="Tomorrow's Plan" supporting="What is planned for the next working day?" action={<AddButton onClick={continueToTomorrow}>Add planned work</AddButton>}><Rows empty="No work planned for tomorrow yet.">{dpr.tomorrowPlan.map(row=><ListRow key={row.id} icon={<ClipboardCheck size={17}/>} title={row.activity} subtitle={row.remarks} value={`${row.planned} ${row.unit}`} onClick={continueToTomorrow}/>)}</Rows></SectionCard>
   <SectionCard id="remarks" number="07" title="General Remarks" supporting="Anything else from site today?" optional><textarea value={dpr.generalRemarks} maxLength={500} onChange={e=>update("generalRemarks",e.target.value)} rows={4} placeholder="Add an optional note…" className="w-full resize-none rounded-[10px] border border-[#e4e4e7] p-3.5 text-[15px] outline-none focus:border-[#e14d48]"/><span className="mt-1 block text-right text-[11px] text-[#8b909d]">{dpr.generalRemarks.length}/500</span></SectionCard>
   <section aria-labelledby="review-submit-title" className="rounded-[18px] border border-black/[.06] bg-white p-5 shadow-[0_6px_20px_rgba(24,24,27,.035)] lg:hidden"><div className="flex items-center gap-3"><span className={`grid size-11 shrink-0 place-items-center rounded-[14px] ${missing.length?"bg-[#f0f3f8] text-[#687080]":"bg-[#e8f7ef] text-[#2d956d]"}`}><ClipboardCheck size={21}/></span><div className="min-w-0"><h2 id="review-submit-title" className="text-[17px] font-bold tracking-[-.025em]">Review &amp; Submit</h2><p className="mt-0.5 text-[12px] text-[#7a808d]">Final check before submission</p></div></div><div className="mt-4 rounded-[13px] bg-[#f6f7f9] px-4 py-3"><strong className="block text-[14px]">{missing.length?`${completed} of 5 required sections complete`:"All required sections complete"}</strong><p className={`mt-1 text-[12px] ${missing.length?"text-[#9a671f]":"text-[#2d8d69]"}`}>{missing.length?`${missing.length} ${missing.length===1?"section":"sections"} remaining`:"Your DPR is ready for review."}</p></div><button onClick={reviewNow} className="mt-4 flex h-[52px] w-full items-center justify-center gap-2 rounded-[13px] bg-[#ed4f49] text-[15px] font-bold text-white shadow-[0_7px_16px_rgba(237,79,73,.16)] active:scale-[.99]">Review DPR <ChevronRight size={18}/></button></section>
  </div><aside className="sticky top-24 hidden rounded-2xl border border-[#e4e4e7] bg-white p-5 lg:block"><p className="text-[13px] font-semibold">DPR progress</p><div className="mt-3 flex items-end justify-between"><strong className="text-[30px]">{percent}%</strong><span className="text-[12px] text-[#71717a]">{completed} of 5 required</span></div><div className="mt-3 h-2 rounded-full bg-[#f0f0f2]"><motion.div animate={{width:`${percent}%`}} className="h-full rounded-full bg-[#e14d48]"/></div><div className="mt-5 space-y-3 text-[13px]">{[["Work Done",dpr.work.length],["Manpower",dpr.manpower.length],["Materials Used",dpr.materials.length],["Site Photos",dpr.photos.length],["Tomorrow's Plan",dpr.tomorrowPlan.length]].map(([name,count])=><div key={String(name)} className="flex items-center justify-between"><span>{name}</span>{Number(count)>0?<Check size={15} className="text-[#3f8f6b]"/>:<span className="text-[#c98932]">Add</span>}</div>)}</div><button onClick={reviewNow} className="mt-6 h-12 w-full rounded-[10px] bg-[#e14d48] text-[14px] font-semibold text-white">Review DPR</button></aside></main>
  <EditorSheets sheet={sheet} setSheet={setSheet} editing={editing} dpr={dpr} setDpr={setDpr} remove={remove} submit={submit}/>
 </div>}

function AddButton({onClick,children}:{onClick:()=>void;children:React.ReactNode}){return <button onClick={onClick} className="focus-ring flex h-11 shrink-0 items-center gap-1 rounded-[10px] px-2 text-[12px] font-semibold text-[#e14d48]"><Plus size={17}/><span className="hidden min-[390px]:inline">Add</span><span className="sr-only">{children}</span></button>}
function Rows({children,empty}:{children:React.ReactNode;empty:string}){return <div className="divide-y divide-[#e4e4e7]">{Array.isArray(children)&&children.length===0?<Empty text={empty}/>:children}</div>}
function Empty({text}:{text:string}){return <div className="w-full min-w-0 rounded-[10px] bg-[#f7f8fa] px-4 py-3.5 text-[13px] leading-5 text-[#71717a] [overflow-wrap:anywhere]">{text}</div>}
function ListRow({icon,title,subtitle,value,onClick}:{icon:React.ReactNode;title:string;subtitle?:string;value:string;onClick:()=>void}){return <button onClick={onClick} className="group grid min-h-16 w-full min-w-0 grid-cols-[40px_minmax(0,1fr)_auto_18px] items-center gap-2.5 py-2 text-left sm:gap-3"><span className="grid size-10 place-items-center rounded-[10px] bg-[#f4f4f5] text-[#71717a]">{icon}</span><span className="min-w-0"><strong className="block truncate text-[14px]">{title}</strong>{subtitle&&<span className="mt-0.5 block truncate text-[12px] text-[#71717a]">{subtitle}</span>}</span><span className="whitespace-nowrap text-[13px] font-medium">{value}</span><ChevronRight size={16} className="text-[#a1a1aa] group-hover:translate-x-0.5"/></button>}
